# Columns whose absence is tolerated (filled with NULL / a neutral value in sources.py).
OPTIONAL = {
    ("syn_scout_reports", "status"),
    ("syn_scout_reports", "distance_m"),
    ("syn_scouts", "last_active_at"),
    ("syn_venue_attributes", "is_claimed"),
    ("syn_venue_attributes", "opening_hours"),
    ("syn_bounties", "expires_at"),
    ("syn_bounties", "claimed_at"),
}
OPTIONAL_TABLES = {"syn_disputes", "syn_users", "syn_feedback"}


def read_schema(path: str) -> dict[str, set[str]]:
    conn = sqlite3.connect(f"file:{path}?mode=ro", uri=True)
    try:
        tables = [r[0] for r in conn.execute("SELECT name FROM sqlite_master WHERE type='table'")]
        return {t: {r[1] for r in conn.execute(f'PRAGMA table_info("{t}")')} for t in tables}
    finally:
        conn.close()


def schema_problems(schema: dict[str, set[str]]) -> list[str]:
    problems = []
    for table, cols in EXPECTED.items():
        if table not in schema:
            if table not in OPTIONAL_TABLES:
                problems.append(f"missing table {table}")
            continue
        miss = [c for c in cols if c not in schema[table] and (table, c) not in OPTIONAL]
        if miss:
            problems.append(f"{table}: missing columns {miss}")
    return problems


def resolve_sim_path(settings: Settings) -> tuple[str | None, list[str]]:
    """Return (path to attach, problems). Real live_sim.db first, fixture only if allowed."""
    if not settings.include_synthetic:
        return None, []
    problems: list[str] = []
    p = Path(settings.live_sim_db)
    if p.exists():
        problems = schema_problems(read_schema(str(p)))
        if not problems:
            return str(p), []
        log.warning("live_sim.db schema mismatch: %s", problems)
    else:
        problems = [f"{p} not found"]
    if settings.allow_fixture_sim:
        fx = Path(settings.fixture_sim_db)
        if not fx.exists():
            from .fixture_sim import build_fixture_sim

            build_fixture_sim(str(fx), settings.launch_venues_csv)
        log.warning("using fixture sim DB %s (%s)", fx, problems)
        return str(fx), problems
    log.error("no usable live_sim.db and ALLOW_FIXTURE_SIM=0: %s", problems)
    return None, problems
